Ext.define('GridHTML.store.OlapStore', {
    extend: 'Ext.Base',

    constructor: function(DashletSpec, Data) {

        var me = this,
            presentTree;

        me.countData = 1;

        me.DashletSpec = DashletSpec;
        me.Data = Data;

        me.cellData = me.Data.queryCommandResult[0].xmla.root.CellData.Cell;

        if (me.cellData.length > 0) {

            presentTree = me.Data.queryCommandResult[2].olapPresentationTree;

            me.olapPresentationTree = presentTree.olapPresentationNode;

            if (presentTree.indented) {
                me.renderMode = "indented";
                me.levelMetadataY = me.getMinLevelByDimension(me.olapPresentationTree[1].dimensions.dimension);
            } else if (presentTree.plain) {
                me.renderMode = "plain";
                me.levelMetadataY = me.getMinLevelByDimension(me.olapPresentationTree[1].dimensions.dimension);
            } else {
                me.renderMode = "default";
            }

            me.levelCountX = me.getLevel(me.olapPresentationTree[0].dimensions);
            me.levelCountY = me.getLevel(me.olapPresentationTree[1].dimensions);

            me.rootPathX = me.depthPath(me.olapPresentationTree[0].dimensions);
            me.rootPathY = me.depthPath(me.olapPresentationTree[1].dimensions);

            me.dimensionX = me.olapPresentationTree[0].dimensions.dimension;
            me.dimensionY = me.olapPresentationTree[1].dimensions.dimension;

            me.treeX = me.olapPresentationTree[0].olapPresentationNodes.olapPresentationNode;
            me.treeY = me.olapPresentationTree[1].olapPresentationNodes.olapPresentationNode;
        } else {
            me.countData = 0;
        }

    },

    getTableSize: function() {

        var me = this,
            treeX = me.treeX,
            treeY = me.treeY,

            unameIndexX = [],
            unameIndexY = [],

            levelCountX = me.levelCountX,
            levelCountY = me.levelCountY,

            toReturn = {
                filas: levelCountX + 2,
                columnas: levelCountY
            },
            cellDataLg = me.cellData.length,
            profundidadX = me.countLeaf(treeX, { unameIndexArray: unameIndexX, index: 0 }),
            profundidadY = me.countLeaf(treeY, { unameIndexArray: unameIndexY, index: 0 });

        toReturn.columnas += profundidadX;
        toReturn.filas += cellDataLg / profundidadX;

        toReturn.dataColumnas = profundidadX;
        toReturn.dataFilas = cellDataLg / profundidadX;

        toReturn.profundidadX = profundidadX;
        toReturn.profundidadY = profundidadY;

        toReturn.levelCountX = me.levelCountX;
        toReturn.levelCountY = me.levelCountY;

        toReturn.rootPathX = me.rootPathX;
        toReturn.rootPathY = me.rootPathY;

        toReturn.unameIndexX = unameIndexX;
        toReturn.unameIndexY = unameIndexY;

        toReturn.levelMetadataY = me.levelMetadataY;

        return toReturn;
    },

    getLevel: function(axe) {

        var me = this,
            ret = 0,
            i = 0,
            tmpLevel;

        if (me.renderMode === "default") {
            for (; i < axe.dimension.length; i++) {
                tmpLevel = axe.dimension[i].levels;
                ret += tmpLevel.level.length;
            }
        } else {
            for (; i < axe.dimension.length; i++) {
                ret += 1;
            }
        }
        return ret;

    },

    getCount: function() {

        return this.countData;

    },

    countLeaf: function(data, indexObj) {
        var i = 0,
            lg = data ? data.length : 0,
            toReturn = 0;

        for (; i < lg; i++) {
            if (data[i].olapPresentationNodes === undefined) {

                indexObj.unameIndexArray[indexObj.index] = data[i].uname;
                indexObj.index++;

                toReturn++;
            } else {
                toReturn += this.countLeaf(data[i].olapPresentationNodes.olapPresentationNode, indexObj);
            }
        }

        return toReturn;

    },

    depthPath: function(axe) {
        var i = 0,
            j = 0,

            dimension = axe.dimension,
            dimensionLg = dimension.length,

            levels,
            levelLg,

            tmpLevel = [];

        for (; i < dimensionLg; i++) {

            levels = dimension[i].levels.level;
            levelLg = levels.length;

            for (j = 0; j < levelLg; j++) {
                tmpLevel.push(dimension[i].name);
            }
        }

        return tmpLevel;
    },

    getMinLevelByDimension: function(dimensions) {

        var i = 0,
            j,
            lg = dimensions.length,
            lg2,
            item, levelItem,
            norm,
            result = [];

        for (; i < lg; i++) {
            item = dimensions[i];

            j = 0;
            levelItem = item.levels.level;
            lg2 = levelItem.length;
            norm = {};

            for (j = 0; j < lg2; j++) {
                norm[levelItem[j].lnum] = j ;
            }

            result.push({
                minLNum: item.minLNum,
                norm: norm
            });
        }
        return result;

    }

});